        setField('ykr-monologue', extractCurrentValue_ykr(ykrData.内心想法));

        setTimeout(() => {
            window.dispatchEvent(new Event('resize'));
        }, 150);
    }

    const MAX_RETRIES_YKR = 5;
    const RETRY_DELAY_YKR = 300;
    let currentRetry_YKR = 0;

    async function fetchDataWithRetry_ykr(msgId) {
        try {
            if (typeof getChatMessages !== 'function') {
                populateFields_ykr(hardcodedInitialData_YKR);
                return;
            }

            const messages = await getChatMessages(msgId);
            let characterData = null;

            if (messages && messages.length > 0 && messages[0].data) {
                characterData = messages[0].data.stat_data || messages[0].data.display_data;
            }

            if (characterData) {
                populateFields_ykr(characterData);
            } else if (String(msgId) === '0' || msgId === 0) {
                populateFields_ykr(hardcodedInitialData_YKR);
            } else {
                currentRetry_YKR++;
                if (currentRetry_YKR < MAX_RETRIES_YKR) {
                    setTimeout(() => fetchDataWithRetry_ykr(msgId), RETRY_DELAY_YKR);
                } else {
                    populateFields_ykr(hardcodedInitialData_YKR); // Fallback after max retries
                }
            }
        } catch (err) {
            populateFields_ykr(hardcodedInitialData_YKR);
        }
    }

    let initialMsgId_ykr = "未知";
    try {
        if (typeof getCurrentMessageId === 'function') {
            initialMsgId_ykr = getCurrentMessageId();
        }
    } catch (e) { /* ignore */ }

    fetchDataWithRetry_ykr(initialMsgId_ykr);
})();
