        "胸乳": ["丰满的雪乳随着呼吸微微晃动，被衬衫紧紧包裹着", ""],
        "腰臀": ["完美的腰臀曲线在牛仔裤的勾勒下若隐若现", ""],
        "小穴": ["干燥的蜜穴被内裤和外裤层层包裹着", ""],
        "肛穴": ["干净的菊穴被内裤包裹着", ""],
        "姿势": ["双手无措地轻放在身前，身体微微前倾", ""],
        "神态": ["面带温和而礼貌的微笑，但眼神中透露出紧张和不安", ""],
        "内心想法": ["是羽的班主任…他怎么会突然来家访？难道是羽在学校又闯了什么大祸吗？", ""]
      }
    };

    function extractCurrentValue_ykr(rawValue, defaultValue = '--') {
        if (rawValue === undefined || rawValue === null) return defaultValue;
        let valueToProcess = Array.isArray(rawValue) && rawValue.length > 0 ? rawValue[0] : rawValue;
        return String(valueToProcess).trim() || defaultValue;
    }

    function updateProgressBarYKR(barId, valueTextId, rawValue, min, max) {
        const progressBar = document.getElementById(barId);
        const valueDisplay = document.getElementById(valueTextId);
        if (!progressBar || !valueDisplay) return;

        const numericString = extractCurrentValue_ykr(rawValue, String(min));
        let numericValue = parseFloat(numericString);
        if (isNaN(numericValue)) {
            valueDisplay.innerText = numericString;
            progressBar.style.width = '0%';
            return;
        }
        valueDisplay.innerText = numericString;
        numericValue = Math.max(min, Math.min(max, numericValue));
        const range = max - min;
        const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
        progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
    }

    function populateFields_ykr(sourceData) {
        const worldData = sourceData.世界 || {};
        const ykrData = sourceData.神户雪柔 || {};

        function setField(id, value) {
            const el = document.getElementById(id);
            if (el) el.innerText = value;
        }

        const worldDateVal = extractCurrentValue_ykr(worldData.当前日期, '日期NA');
        const worldTimeVal = extractCurrentValue_ykr(worldData.当前时间段, '时间NA');
        setField('ykr-world-date', worldDateVal);
        setField('ykr-world-time', worldTimeVal);
        setField('ykr-datetime', `${worldDateVal} ${worldTimeVal}`);
        setField('ykr-location', extractCurrentValue_ykr(ykrData.地点));
        setField('ykr-char-stage', extractCurrentValue_ykr(ykrData.角色阶段));

        updateProgressBarYKR('ykr-favor-bar', 'ykr-favor', ykrData.好感, -20, 100);
        setField('ykr-favor-reason', extractCurrentValue_ykr(ykrData.好感_更新原因));
        updateProgressBarYKR('ykr-love-bar', 'ykr-love', ykrData.爱意, -20, 100);
        setField('ykr-love-reason', extractCurrentValue_ykr(ykrData.爱意_更新原因));
        updateProgressBarYKR('ykr-lust-bar', 'ykr-lust', ykrData.情欲, 0, 100);
        setField('ykr-lust-reason', extractCurrentValue_ykr(ykrData.情欲_更新原因));
        updateProgressBarYKR('ykr-corruption-bar', 'ykr-corruption', ykrData.堕落, 0, 100);
        setField('ykr-corruption-reason', extractCurrentValue_ykr(ykrData.堕落_更新原因));

        setField('ykr-top', extractCurrentValue_ykr(ykrData.上装));
        setField('ykr-bottom', extractCurrentValue_ykr(ykrData.下装));
        setField('ykr-panties', extractCurrentValue_ykr(ykrData.内裤));
        setField('ykr-stockings', extractCurrentValue_ykr(ykrData.丝袜));
        setField('ykr-shoes', extractCurrentValue_ykr(ykrData.鞋子));

        setField('ykr-posture', extractCurrentValue_ykr(ykrData.姿势));
        setField('ykr-expression', extractCurrentValue_ykr(ykrData.神态));
        setField('ykr-mouth', extractCurrentValue_ykr(ykrData.嘴舌));
        setField('ykr-breasts', extractCurrentValue_ykr(ykrData.胸乳));
        setField('ykr-waist', extractCurrentValue_ykr(ykrData.腰臀));
        setField('ykr-pussy', extractCurrentValue_ykr(ykrData.小穴));
        setField('ykr-anus', extractCurrentValue_ykr(ykrData.肛穴));
        setField('ykr-monologue', extractCurrentValue_ykr(ykrData.内心想法));

        setTimeout(() => {
            window.dispatchEvent(new Event('resize'));
        }, 150);
    }

    const MAX_RETRIES_YKR = 5;
    const RETRY_DELAY_YKR = 300;
    let currentRetry_YKR = 0;

    async function fetchDataWithRetry_ykr(msgId) {
        try {
            if (typeof getChatMessages !== 'function') {
                populateFields_ykr(hardcodedInitialData_YKR);
                return;
            }

            const messages = await getChatMessages(msgId);
            let characterData = null;

            if (messages && messages.length > 0 && messages[0].data) {
                characterData = messages[0].data.stat_data || messages[0].data.display_data;
            }

            if (characterData) {
                populateFields_ykr(characterData);
            } else if (String(msgId) === '0' || msgId === 0) {
                populateFields_ykr(hardcodedInitialData_YKR);
            } else {
                currentRetry_YKR++;
                if (currentRetry_YKR < MAX_RETRIES_YKR) {
                    setTimeout(() => fetchDataWithRetry_ykr(msgId), RETRY_DELAY_YKR);
                } else {
                    populateFields_ykr(hardcodedInitialData_YKR); // Fallback after max retries
                }
            }
        } catch (err) {
            populateFields_ykr(hardcodedInitialData_YKR);
        }
    }

    let initialMsgId_ykr = "未知";
    try {
        if (typeof getCurrentMessageId === 'function') {
            initialMsgId_ykr = getCurrentMessageId();
        }
    } catch (e) { /* ignore */ }

    fetchDataWithRetry_ykr(initialMsgId_ykr);
})();
</script>
